INSERT INTO products (name, slug, sku, price, cost_price, description, specifications, status, category_id, brand_id, created_at, updated_at) VALUES ('Tai nghe Samsung Galaxy Buds 4', 'tai-nghe-samsung-galaxy-buds-4', 'CP-TAINGHES-9BD501', 3990000.0, 3391500.0, 'Tai nghe Samsung Galaxy Buds 4 chính hãng, chất âm cải tiến Hi-Fi cao cấp, tích hợp Galaxy AI. Mua Galaxy Buds4 giá tốt, trả góp 0% tại CellphoneS', '{"Kích thước ": "tai nghe: 18.3x19.3x30.5mm  hộp sạc: 51x51x28.3mm", "Trọng lượng ": "tai nghe: 4.6g  hộp sạc: 45.1g", "Thời lượng sử dụng Pin": "Bật ANC: tai nghe 5h, hộp sạc + tai nghe 24h  Tắt ANC: tai nghe 6h, hộp sạc + tai nghe 30h", "Tính năng khác": "Bộ khuếch đại đơn", "Hãng sản xuất": "Samsung Chính hãng"}', 'ACTIVE', 4, 2, NOW(), NOW()) ON DUPLICATE KEY UPDATE category_id = 4, brand_id = 2, price = 3990000.0, specifications = '{"Kích thước ": "tai nghe: 18.3x19.3x30.5mm  hộp sạc: 51x51x28.3mm", "Trọng lượng ": "tai nghe: 4.6g  hộp sạc: 45.1g", "Thời lượng sử dụng Pin": "Bật ANC: tai nghe 5h, hộp sạc + tai nghe 24h  Tắt ANC: tai nghe 6h, hộp sạc + tai nghe 30h", "Tính năng khác": "Bộ khuếch đại đơn", "Hãng sản xuất": "Samsung Chính hãng"}';
